package com.mamtrex.hospital.staff;
import com.mamtrex.hospital.audit.AuditService; import com.mamtrex.hospital.shared.NotFoundException; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/staff") public class StaffMemberController { private final StaffMemberRepository repo; private final AuditService audit; public StaffMemberController(StaffMemberRepository r,AuditService a){repo=r;audit=a;} public record Request(@jakarta.validation.constraints.NotBlank String employeeCode, @jakarta.validation.constraints.NotBlank String fullName, @jakarta.validation.constraints.NotBlank String profession, @jakarta.validation.constraints.NotBlank String licenseNumber, @jakarta.validation.constraints.NotBlank String department){} @PostMapping public StaffMember create(@Valid @RequestBody Request r){var e=repo.save(new StaffMember(r.employeeCode(), r.fullName(), r.profession(), r.licenseNumber(), r.department()));audit.record("CREATE","StaffMember",e.getId().toString(),"created");return e;} @GetMapping public List<StaffMember> list(){return repo.findAll();} @GetMapping("/{id}") public StaffMember get(@PathVariable UUID id){return repo.findById(id).orElseThrow(()->new NotFoundException("StaffMember not found: "+id));} @DeleteMapping("/{id}") public void delete(@PathVariable UUID id){if(!repo.existsById(id))throw new NotFoundException("StaffMember not found: "+id);repo.deleteById(id);audit.record("DELETE","StaffMember",id.toString(),"deleted");} }
